const groupLogsByType = (
  rawLogs: T.BuildLog[],
  filterType: FilterState,
): FilteredLog[] => {
  const logs = rawLogs.map((l, index) => ({ ...l, index }));
  if (filterType === 'all' || logs.length === 0) {
    return [{ hidden: false, logs }];
  }

  const filteredLogs: FilteredLog[] = [];

  let currentGroup: FilteredLog = { hidden: false, logs: [] };
  let previousGroupType: FilterState | undefined;

  for (const log of logs) {
    const logType = log.error ? 'errors' : log.warning ? 'warnings' : 'all';
    if (logType !== previousGroupType) {
      filteredLogs.push(currentGroup);
      currentGroup = { hidden: logType !== filterType, logs: [log] };
      previousGroupType = logType;
    } else {
      currentGroup.logs.push(log);
    }
  }

  filteredLogs.push(currentGroup);

  const compactedGroups = filteredLogs.reduce((prev, cur) => {
    const isCurrentGroupHidden = cur.hidden;
    const previousGroup = prev.slice(-1)[0];
    const isPreviousGroupHidden = previousGroup !== undefined ? previousGroup.hidden : false;

    if (isCurrentGroupHidden === isPreviousGroupHidden) {
      previousGroup!.logs.push(...cur.logs);
      return prev.slice(0, -1);
    }
    return [...prev, cur];
  }, []);

  return compactedGroups;
};
