```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Pendulum Simulator</title>
    <style>
        #pendulum {
            position: relative;
            display: inline-block;
            margin: 20px;
            width: 200px;
            height: 200px;
            border: 1px solid black;
        }
        .pendulum-string {
            position: absolute;
            top: 0;
            left: 50%;
            transform: translateX(-50%);
            width: 100%;
            height: 100%;
            background-color: #ccc;
            border-radius: 50%;
        }
        .pendulum-bob {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            width: 10px;
            height: 10px;
            background-color: #333;
            border-radius: 50%;
        }
    </style>
</head>
<body>
    <input id="initial-angle" type="number" value="45" />
    <button id="release-button">Release</button>
    <div id="pendulum"></div>
    <script>
        let initialAngle = 45;
        let length = 100;
        let gravity = 9.81;
        let bobRadius = 5;
        let stringWidth = 10;
        let stringHeight = 100;
        let angle = 0;
        let velocity = 0;
        let animationFrame = 0;
        let isRunning = false;
        let container = document.getElementById('pendulum');

        function setup() {
            let pendulum = document.createElement('div');
            pendulum.className = 'pendulum-string';
            pendulum.style.width = `${length}px`;
            pendulum.style.height = `${stringHeight}px`;
            pendulum.style.borderRadius = stringWidth / 2;

            let bob = document.createElement('div');
            bob.className = 'pendulum-bob';
            bob.style.width = `${bobRadius * 2}px`;
            bob.style.height = `${bobRadius * 2}px`;
            bob.style.top = `${initialAngle * Math.PI / 180 * length}px`;
            bob.style.left = `${length / 2}px`;
            bob.style.returnValue = 'none';
            bob.style.background = 'black';

            pendulum.appendChild(bob);
            container.appendChild(pendulum);

            document.getElementById('release-button').addEventListener('click', function() {
                isRunning = true;
                startAnimation();
            });
        }

        function update() {
            angle += velocity;
            velocity -= gravity / length * Math.sin(angle);

            let bobPos = length / 2 + bobRadius * Math.sin(angle);
            let bobTop = `-${bobPos}px`;
            document.querySelector('.pendulum-string .pendulum-bob').style.top = bobTop;

            if (velocity < 0.1 && angle < 0.1) {
                velocity = 0;
                angle = 0;
                isRunning = false;
            }
        }

        function startAnimation() {
            if (!isRunning) {
                return;
            }
            requestAnimationFrame(startAnimation);
            update();
        }

        setup();
    </script>
</body>
</html>
```

